import type { ReactNode } from "react"
import { Button as HeroUIButton, Spinner, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import {
    ALIGN_CLS,
    HERO_VARIANT,
    ICON_CLS,
    ICON_WEIGHT,
    LABEL_SIZE,
    SKELETON_H,
    SKELETON_SQUARE,
    SKELETON_W,
    VARIANT_CLS,
    type ButtonAlign,
    type ButtonSize,
    type ButtonVariant,
    type IconComponent,
} from "./button-tokens"

/**
 * ATOM — `Button`: a button with a label.
 *
 * One prop = one leaf: each visual prop gets its own leaf rendering that prop's full
 * value set — `variant` · `size` · `prefixIcon` · `suffixIcon` · `iconSlide` ·
 * `isIconOnly` · `isDisabled` · `isPending` · `isSkeleton`.
 *
 * Icons = Phosphor; the atom forces both scale and `weight` off `size`.
 */

/** Props shared across all three shapes below — see {@link ButtonBaseProps} for the `label`/`isIconOnly`/`isSkeleton` union. */
interface ButtonBaseOwnProps {
    /**
     * Leading glyph passed as a component (`prefixIcon={PlusIcon}`, not JSX). When
     * `isIconOnly` this is the button's only glyph. Scale and stroke weight are derived from `size`.
     */
    prefixIcon?: IconComponent
    /**
     * Trailing glyph, after the label. Same scale/weight rule as `prefixIcon`.
     * Meaningless when `isIconOnly` — the button has only one glyph slot then.
     */
    suffixIcon?: IconComponent
    /**
     * Slides the glyph on hover: `prefixIcon` retreats left, `suffixIcon` advances
     * right. Use only for navigation arrows — a static caret/glyph gains nothing from it.
     */
    iconSlide?: boolean
    /** Action intent → HeroUI variant. Default `primary`. */
    variant?: ButtonVariant
    /** Button scale. Default `md`. Glyph size follows automatically — the caller does not set it. */
    size?: ButtonSize
    /**
     * `true` adds `shadow-lg`, for a button that floats above its background (e.g.
     * a floating action button). HeroUI's default has no shadow — only a
     * `transition: box-shadow` prepared for one (see `button.css`).
     */
    isElevated?: boolean
    /** Where the glyph+label row sits inside the button. Default centered (HeroUI's own default). See {@link ButtonAlign}. */
    align?: ButtonAlign
    onPress?: () => void
    /** `true` disables the button (forwarded to HeroUI, OR'd with `isPending`). */
    isDisabled?: boolean
    /** `true` marks the button busy: a spinner replaces the leading glyph and the press handler locks. */
    isPending?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Three mutually exclusive shapes, enforced at compile time:
 *   - skeleton — no label needed (a shimmer has no text).
 *   - icon-only — `prefixIcon` + `ariaLabel` required, no label.
 *   - labeled — `label` required.
 */
export type ButtonBaseProps = ButtonBaseOwnProps &
    (
        | { isSkeleton: true; isIconOnly?: boolean; label?: ReactNode; ariaLabel?: string }
        | { isSkeleton?: false; isIconOnly: true; prefixIcon: IconComponent; ariaLabel: string; label?: never }
        | { isSkeleton?: false; isIconOnly?: false; label: ReactNode; ariaLabel?: string }
    )

/** Shared button chrome — variants, sizes, icons, skeleton, pending, and press handling. */
export const ButtonBase = ({
    label,
    prefixIcon: PrefixIcon,
    suffixIcon: SuffixIcon,
    iconSlide = false,
    isIconOnly = false,
    ariaLabel,
    variant = "primary",
    size = "md",
    isElevated = false,
    align,
    onPress,
    isDisabled = false,
    isPending = false,
    isSkeleton = false,
    classNames,
}: ButtonBaseProps) => {
    if (isSkeleton) {
        // Square when icon-only, pill when labeled.
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="Button"
                className={cn(
                    "rounded-full",
                    isIconOnly ? SKELETON_SQUARE[size] : cn(SKELETON_W[size], SKELETON_H[size]),
                    classNames,
                )}

            />
        )
    }

    /** Leading glyph — or a spinner in its place when busy, never both at once. */
    const leading = isPending ? (
        <span aria-hidden className="inline-flex shrink-0">
            <Spinner size="sm" color="current" />
        </span>
    ) : PrefixIcon ? (
        <span
            aria-hidden
            className={cn(
                "inline-flex shrink-0",
                ICON_CLS[size],
                // Tailwind v4 treats `translate` as its own property — needs `transition-[translate]`, not `-transform`.
                iconSlide && "transition-[translate] group-hover:-translate-x-0.5",
            )}
        >
            <PrefixIcon weight={ICON_WEIGHT[size]} />
        </span>
    ) : null

    return (
        <HeroUIButton
            data-tier="atom"
            data-component="Button"
            isIconOnly={isIconOnly}
            variant={HERO_VARIANT[variant]}
            size={size}
            aria-label={ariaLabel}
            onPress={onPress}
            isPending={isPending}
            isDisabled={isDisabled || isPending}
            className={cn("group", VARIANT_CLS[variant], isElevated && "shadow-lg", align && ALIGN_CLS[align], classNames)}

        >
            {leading}
            {isIconOnly ? null : (
                // Raw `<span>` — ATOM-3 forbids an atom from importing another house
                // atom (`Typography`), so the label cannot go through it. `truncate`
                // clips the label at an ellipsis; `min-w-0` is required on the
                // label's own flex-row slot: flex items default to `min-width: auto`,
                // which floors them at their content's natural width and blocks
                // `text-overflow: ellipsis` from ever firing.
                //
                // Size/weight/color are spelled out explicitly rather than left to
                // inherit from `.button`: `LABEL_SIZE[size]` mirrors `button.css`'s
                // own rule (`.button` is `text-sm`, `.button--lg` overrides to
                // `text-base`); `font-medium` mirrors `.button`'s base weight;
                // `text-[var(--button-fg)]` reads the same per-variant CSS custom
                // property `.button--<variant>` sets (see `button.css` in
                // `@heroui/styles`) that the label inherited for free before this
                // ever went through Typography — so every variant (not just
                // `secondary`) gets its real foreground back.
                <span className={cn(LABEL_SIZE[size], "font-medium truncate min-w-0 text-[var(--button-fg)]")}>{label}</span>
            )}
            {!isIconOnly && SuffixIcon ? (
                // Trailing glyph — advances right on hover when iconSlide is set.
                <span
                    aria-hidden
                    className={cn(
                        "inline-flex shrink-0",
                        ICON_CLS[size],
                        iconSlide && "transition-[translate] group-hover:translate-x-0.5",
                    )}
                >
                    <SuffixIcon weight={ICON_WEIGHT[size]} />
                </span>
            ) : null}
        </HeroUIButton>
    )
}

/** Tier metadata for `Button`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "Button" } as const

import type { ComponentType, ReactNode, SVGProps } from "react"
import { Chip as HeroChip, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import { CircleIcon, XIcon } from "@phosphor-icons/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ATOM — `Chip`: the only chip in the system.
 *
 * One prop = one leaf, each rendering every state the prop can produce: `tone` ·
 * `icon` · colour dot · `onRemove` · `isSkeleton`. Props that produce no visual
 * (`removeLabel`, `className`, `showAnatomy`) get no leaf.
 *
 * Icon = Phosphor; the atom pins both the scale (`size-3`, matching the chip's text)
 * and the `weight`.
 */

/**
 * Chip's semantic tone → HeroUI's soft color.
 *
 * Kept as its own type rather than aliased to `AlertStatus`: `tone` flows straight into
 * HeroUI's `HeroChip.color`, a vendor prop with a closed union that has no `"info"`.
 * `ChipTone` must stay in sync 1:1 with that real union (5 values, no `info`).
 */
export type ChipTone = "default" | "accent" | "success" | "warning" | "danger"

/**
 * Icon passed as a COMPONENT (e.g. `CheckCircleIcon`); the atom renders it at chip scale.
 *
 * The type stays open (`SVGProps` + optional `weight`) instead of declaring Phosphor's
 * `Icon` type, so it doesn't lock the tree to one icon library. `weight` lets the atom
 * force the stroke weight on whatever icon is passed — only `regular`/`bold`.
 */
export type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/**
 * Icon scale matches the chip's font scale: HeroUI's chip renders `text-xs` (12px) at
 * `md`, so the glyph is `size-3`. No `!important` needed here (unlike `Button`) —
 * `chip.css` has no `.chip svg` rule to out-specify.
 */
const ICON_CLS = "size-3"

/** 6px dot — under the `size-5` threshold, so it renders at heavy weight (`fill`). */
const DOT_PX = 6

/**
 * Skeleton width by slot count: label only · label + one cell (leading glyph or ×
 * button) · label + both. Must match the real chip's footprint, or the row jumps when
 * data loads.
 */
const SKELETON_W = ["w-16", "w-20", "w-24"] as const

/** Shared props — excludes `text`/`isSkeleton` and the leading-glyph slot; see {@link ChipBaseProps}. */
interface ChipBaseOwnProps {
    /** Semantic tone → soft color. Default `default` (neutral). */
    tone?: ChipTone
    /** When provided, the chip renders a trailing × button that calls this on click. */
    onRemove?: () => void
    /** Accessibility label for the × button (caller supplies the translated string). */
    removeLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The leading-glyph cell has one slot, so `icon` and the dot are mutually exclusive at
 * compile time. The dot shows only when the caller gives it a color — an uncolored dot
 * is meaningless, so there's no separate `hasDot` boolean (that would allow the
 * nonsensical state of `hasDot` true with no color).
 */
type ChipLeadingProps =
    | { icon?: IconComponent; dotColor?: never; dotClassName?: never }
    | {
          icon?: never
          /**
           * Raw hex color for the dot (e.g. `#3178c6`, GitHub's language color) — for
           * colors outside the Tailwind token palette. Takes precedence over
           * `dotClassName`; both use the same `currentColor` mechanism.
           */
          dotColor?: string
          /**
           * Tailwind text-color class for the dot (e.g. `text-success`). The dot is a
           * `CircleIcon weight="fill"` that reads `currentColor`, so this class on the
           * parent span sets its color; the chip's own text still follows `tone`.
           */
          dotClassName?: string
      }

/**
 * `text` is required when rendering a real chip; not needed when `isSkeleton` — the
 * pill shimmer has no label.
 */
export type ChipBaseProps = ChipBaseOwnProps &
    ChipLeadingProps &
    ({ isSkeleton: true; text?: ReactNode } | { isSkeleton?: false; text: ReactNode })

/** Shared chip chrome — tone, leading icon/dot, removable trailing X, and skeleton. */
export const ChipBase = ({
    tone = "default",
    text,
    icon: Icon,
    dotColor,
    dotClassName,
    onRemove,
    removeLabel,
    isSkeleton = false,
    classNames,
}: ChipBaseProps) => {
    // The dot appears only when the caller gives it a color (see {@link ChipLeadingProps}).
    const hasDot = dotColor != null || dotClassName != null

    if (isSkeleton) {
        // Skeleton branch checked before any shape branch. Renders the real `HeroChip`
        // with shimmer content inside, so height/radius/padding come straight from
        // `.chip` instead of a hand-copied constant that could drift out of sync.
        const slots = (hasDot || Icon ? 1 : 0) + (onRemove ? 1 : 0)
        return (
            <HeroChip
                data-tier="atom"
                data-component="Chip"
                color={tone}
                variant="soft"
                className={cn("w-fit", classNames)}
                // Node name = the REAL component rendered here (HeroUI `Chip`, in its
                // loading look) — NOT the word "Skeleton" (that's a STATE, not an
                // identity, and this element is the same `HeroChip` the real branch
                // below renders).

            >
                {hasDot || Icon ? <HeroSkeleton className="size-3 shrink-0 rounded-full" /> : null}
                <HeroChip.Label>
                    {/* Width is guessed (text length unknown). Height is not: it must equal
                        `leading-5`, the line-height `.chip` sets for real text — a shimmer
                        bar has no line-height of its own, so without this the box renders
                        shorter than the real chip (16px vs 24px), and `.chip` still adds
                        its own `py-0.5` on top. */}
                    <HeroSkeleton className={cn("h-5 rounded", SKELETON_W[slots])} />
                </HeroChip.Label>
                {onRemove ? <HeroSkeleton className="size-3 shrink-0 rounded-full" /> : null}
            </HeroChip>
        )
    }

    /** Leading glyph: colored dot or icon — never both (enforced by the type). */
    const leading = hasDot ? (
        <span
            aria-hidden
            className={cn("inline-flex shrink-0", dotClassName)}
            style={dotColor ? { color: dotColor } : undefined}
        >
            {/* Solid dot = `CircleIcon weight="fill"` (Phosphor has no separate `*Fill`
                variant); fill defaults to `currentColor`, so the color set on the parent
                span carries through. */}
            <CircleIcon weight="fill" width={DOT_PX} height={DOT_PX} />
        </span>
    ) : Icon ? (
        <span aria-hidden className="inline-flex shrink-0">
            {/* The atom owns glyph scale: matches the chip's font size, and since it's
                under `size-5` it renders bold. */}
            <Icon className={ICON_CLS} weight="bold" />
        </span>
    ) : null

    return (
        <HeroChip
            data-tier="atom"
            data-component="Chip"
            color={tone}
            variant="soft"
            // No `size` passed — this is HeroUI's base size already. `chipVariants
            // .defaultVariants` doesn't declare `size`, and `.chip--md` only adds
            // `text-xs`, which `.chip` already has — so `size="md"` would be a no-op
            // that reads as a real decision but isn't.
            //
            // Don't lower the size to fix how one chip looks: the atom uses one scale
            // everywhere, so a chip that looks too big at some call site belongs in a
            // different context there, not a smaller `size`.
            //
            // w-fit: chip is a content-hugging pill — without it, `align-items: stretch`
            // on a flex-col parent stretches the chip the full row.
            className={cn("w-fit", classNames)}

        >
            {leading}
            {/* Real component rendered here is HeroUI's `Chip.Label` compound member —
                name the node after it, not the generic slot word "Label". */}
            <HeroChip.Label>{text}</HeroChip.Label>
            {onRemove ? (
                // × button sized to the chip (size-4 hit area, size-3 glyph), takes the
                // chip's tone via `currentColor` — not `Button isIconOnly` (that's ~32px,
                // too big for a 24px chip). This is an action (remove), so it must be a
                // real `<button>`, not a link.
                <button
                    type="button"
                    aria-label={removeLabel ?? "Remove"}
                    onClick={onRemove}
                    className="inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-full opacity-70 outline-none transition hover:bg-current/15 hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-accent [&_svg]:size-3"
                >
                    {/* × is forced to size-3 (< size-5), so it renders bold. */}
                    <XIcon aria-hidden weight="bold" />
                </button>
            ) : null}
        </HeroChip>
    )
}

/** Tier metadata for `Chip`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "Chip" } as const

"use client"

import { useMemo, useState } from "react"
import type { ComponentType, SVGProps } from "react"
import { Avatar as HeroAvatar, AvatarImage as HeroAvatarImage, AvatarFallback as HeroAvatarFallback, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ATOM — `Avatar`: the system's one avatar, wrapping HeroUI `Avatar` directly.
 *
 * One prop = one leaf, each of the props with a shape: `Default` · `Source` (the
 * src → generated → initials → icon fallback chain, including the failed-load case) ·
 * `Fallback` · `Status` (4 tones) · `Sizes` (3 tiers) · `Colors` (5 tints) ·
 * `Skeleton`. A prop with no shape (`className`) gets no leaf. Each `states[]` entry
 * renders exactly one `Avatar` instance.
 *
 * Icon = Phosphor — pass the component (`icon={UserIcon}`), not JSX; the atom forces
 * the scale and weight from `size`.
 */

/**
 * Icon stroke weight; the atom picks between these two based on `size`.
 * Declared locally instead of importing phosphor's own type, so this file
 * does not depend on one icon provider.
 */
export type IconWeight = "regular" | "bold"

/**
 * An icon passed as a COMPONENT (e.g. `UserIcon`), rendered by the atom at
 * avatar scale. Typed as `SVGProps` plus `weight`, independent of any icon library.
 */
export type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: IconWeight }>

/** Presence status → status-dot tone (the SINGLE source for status colour). */
export type AvatarStatus = "online" | "offline" | "busy" | "away"

/**
 * Decorative frame tone — a ring drawn around the avatar. The atom owns the
 * ring's shape; the caller only names the tone.
 */
export type AvatarRing = "warning" | "accent"

/** Avatar size preset. */
export type AvatarSize = "sm" | "md" | "lg"

/** Fallback tint when initials/icon show (HeroUI avatar `color`). */
export type AvatarColor = "accent" | "danger" | "default" | "success" | "warning"

/**
 * What shows when there is no `src`. `"generated"` (default) adds DiceBear to
 * the image candidate chain; `"initials"` / `"icon"` skip it and show the
 * initials or icon directly.
 */
export type AvatarFallback = "generated" | "initials" | "icon"

/** Status-dot background tone keyed by avatar status. */
export const STATUS_TONE: Record<AvatarStatus, string> = {
    online: "bg-success",
    offline: "bg-default-400",
    busy: "bg-danger",
    away: "bg-warning",
}

/** `ring` tone → the ring's own colour utility (paired with the shared frame shape below). */
export const RING_TONE: Record<AvatarRing, string> = {
    warning: "ring-warning",
    accent: "ring-accent",
}

/** Frame shape shared by every ring tone — only the colour utility (`RING_TONE`) varies. */
const RING_FRAME = "rounded-full ring-2 ring-offset-2 ring-offset-background"

/**
 * Per-size chrome: skeleton box, status-dot diameter, fallback glyph scale
 * and weight. Class set one avatar size resolves to.
 */
export interface AvatarSizeStyle {
    /** Box size of the avatar itself. */
    box: string
    /** Size of the status dot. */
    dot: string
    /** Size of the fallback glyph. */
    glyph: string
    /** Stroke weight for the glyph; `undefined` means the `weight` prop is omitted entirely. */
    glyphWeight?: IconWeight
}

/** Per-size chrome for avatar box, status dot, and fallback glyph. */
export const SIZE_MAP: Record<AvatarSize, AvatarSizeStyle> = {
    sm: { box: "size-8", dot: "size-2", glyph: "size-4", glyphWeight: "bold" },
    md: { box: "size-10", dot: "size-2.5", glyph: "size-5" },
    lg: { box: "size-12", dot: "size-3", glyph: "size-6" },
}

/**
 * Builds a stable DiceBear "thumbs" avatar URL from a seed — the same seed
 * always yields the same face. Mirrors `src/utils/avatar.ts#dicebearAvatarUrl`;
 * duplicated here (not imported) so this Storybook atom stays self-contained.
 *
 * @param seed - stable identity string (prefer email/username, then name)
 * @returns DiceBear SVG avatar URL
 */
export const dicebearAvatarUrl = (seed: string): string =>
    `https://api.dicebear.com/9.x/thumbs/svg?seed=${encodeURIComponent(seed || "anonymous")}`

/** Props for {@link AvatarBase}. */
export interface AvatarBaseProps {
    /** Uploaded image URL. Absent → the atom falls back per `fallback`. */
    src?: string
    /**
     * Stable identity used to seed the generated (DiceBear) avatar — email or
     * username, so the same person always gets the same generated face. Falls
     * back to `name` when omitted.
     */
    seed?: string
    /** Display name: drives image `alt` + the initials fallback (first two letters). */
    name?: string
    /**
     * Exact fallback text, not sliced to two letters — for overflow chips (`+12`)
     * where initials would corrupt the count.
     */
    exactLabel?: string
    /** Fallback glyph as a COMPONENT reference (shown per the `fallback` chain). */
    icon?: IconComponent
    /** What to show when there is no `src`. Default `"generated"` (DiceBear). */
    fallback?: AvatarFallback
    /** When set → renders a presence dot at the bottom-right, tinted by status. */
    status?: AvatarStatus
    /**
     * When set → draws a decorative frame ring around the avatar, tinted by
     * tone (`"warning"` strongest, `"accent"` quieter). Omit for no ring. The
     * atom owns the ring's shape; the caller only names the tone. See {@link AvatarRing}.
     */
    ring?: AvatarRing
    /** Size preset. Default `md`. */
    size?: AvatarSize
    /** Fallback tint (initials/icon). Default `default`. */
    color?: AvatarColor
    /** Render the leaf skeleton (a circle shimmer) instead of the avatar. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The base avatar atom. See file header for the strict fallback-chain + icon contract.
 *
 * @param props - {@link AvatarBaseProps}
 */
export const AvatarBase = ({
    src,
    seed,
    name,
    exactLabel,
    icon: Icon,
    fallback = "generated",
    status,
    ring,
    size = "md",
    color = "default",
    isSkeleton = false,
    classNames,
}: AvatarBaseProps) => {
    const { box, dot, glyph, glyphWeight } = SIZE_MAP[size]

    // Checked before any other branch: while skeleton, still draws the status
    // wrapper/dot (neutral tone, unknown status) so loading and loaded layouts
    // match pixel-for-pixel.
    if (isSkeleton) {
        return (
            <span
                data-tier="atom"
                data-component="Avatar"
                className={cn("relative inline-flex", ring ? cn(RING_FRAME, RING_TONE[ring]) : undefined, classNames)}
            >
                <HeroSkeleton className={cn("rounded-full", box)} />
                {status ? (
                    <span
                        aria-hidden

                        className={cn("ring-background absolute bottom-0 right-0 rounded-full ring-2", dot, "bg-default-300")}
                    />
                ) : null}
            </span>
        )
    }

    // Image candidates in order: src (if any) → DiceBear generated from seed ?? name.
    // fallback="initials"/"icon" excludes DiceBear from the chain (src only, if present).
    const candidates = useMemo(() => {
        if (exactLabel) return []
        const uploaded = src?.trim()
        if (fallback !== "generated") return uploaded ? [uploaded] : []
        const generated = dicebearAvatarUrl(seed ?? name ?? "")
        return uploaded ? [uploaded, generated] : [generated]
    }, [src, seed, name, fallback, exactLabel])

    // Index of the candidate currently being tried; advances on load ERROR, not
    // just a missing URL (see onLoadingStatusChange note above). Keyed by the
    // candidate chain's signature, so changing src/seed/name/fallback resets to 0.
    const signature = candidates.join("|")
    const [state, setState] = useState({ signature, index: 0 })
    const index = state.signature === signature ? state.index : 0
    const imageSrc = candidates[index]

    // Once image candidates are exhausted: fallback="icon" shows the glyph
    // directly; otherwise initials take priority, dropping to the icon only
    // when `name` is empty.
    const initials = exactLabel ?? (name ?? "").trim().slice(0, 2).toUpperCase()
    const iconGlyph = Icon ? (
        <span aria-hidden className="inline-flex">
            <Icon className={glyph} weight={glyphWeight} />
        </span>
    ) : null
    const fallbackContent = fallback === "icon" && iconGlyph ? iconGlyph : initials || iconGlyph

    return (
        // Relative wrapper so the status dot can anchor to the bottom-right corner.
        // `classNames` applies here too, matching the skeleton branch above, so
        // caller positioning stays consistent across the loading/loaded transition.
        <span
            data-tier="atom"
            data-component="Avatar"
            className={cn("relative inline-flex", ring ? cn(RING_FRAME, RING_TONE[ring]) : undefined, classNames)}
        >
            <HeroAvatar size={size} color={color} className="rounded-full">
                {imageSrc ? (
                    <HeroAvatarImage
                        src={imageSrc}
                        alt={name ?? ""}

                        onLoadingStatusChange={(loadStatus) => {
                            if (loadStatus === "error") {
                                setState({ signature, index: index + 1 })
                            }
                        }}
                    />
                ) : null}
                <HeroAvatarFallback>{fallbackContent}</HeroAvatarFallback>
            </HeroAvatar>
            {status ? (
                <span
                    aria-hidden

                    className={cn(
                        "ring-background absolute bottom-0 right-0 rounded-full ring-2",
                        dot,
                        STATUS_TONE[status],
                    )}
                />
            ) : null}
        </span>
    )
}

/** Tier metadata for `Avatar`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "Avatar" } as const

import type { ReactNode } from "react"
import { Badge as HeroBadge, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ATOM — `Badge`: wraps HeroUI `Badge` directly (+ `Badge.Anchor` when it has
 * `children`). A leaf atom — it composes none of our own storied atoms, so it has no
 * atom-tier deps; `Content` is an internal slot for free-form `children`, not a dep.
 * `Badge`/`Badge.Anchor`/`Skeleton` are direct `@heroui/react` renders (`tier:
 * "heroui"`), and `Badge` is a valid atom-wrapper holding `children`.
 *
 * Uses the `states[]` API: each prop value (`count`/`dot`/`max` for `Anchored`, each
 * tone for `Colors`, each size for `Sizes`, each corner for `Placement`) is its own
 * state, so the deps tree and code snippet belong to it alone.
 */

/** Badge tone (HeroUI Badge `color`). */
export type BadgeColor = "accent" | "danger" | "default" | "success" | "warning"

/** Corner the badge anchors to on its child. */
export type BadgePlacement = "top-right" | "top-left" | "bottom-right" | "bottom-left"

/** Props for {@link BadgeBase}. */
export interface BadgeBaseProps {
    /** Element the badge anchors to (icon / avatar). Absent → the badge renders inline, standalone. */
    children?: ReactNode
    /** Numeric count. Rendered verbatim until it exceeds {@link BadgeBaseProps.max}. Ignored when `dot`. */
    count?: number
    /** Cap: counts above this render as `"{max}+"` (e.g. `99` → `"99+"`). */
    max?: number
    /** Render a bare dot (no number) — a presence/unread signal. */
    dot?: boolean
    /** Keep the badge visible at `count === 0`. Default `false` (zero hides the badge). */
    showZero?: boolean
    /** Badge tone. Default `danger` (the usual unread/alert colour). */
    color?: BadgeColor
    /** Badge size. Default `md`. */
    size?: "sm" | "md" | "lg"
    /** Anchor corner (only meaningful with `children`). Default `top-right`. */
    placement?: BadgePlacement
    /** Render the leaf skeleton (a small pill/dot shimmer) instead of the badge. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The base badge atom. See file header for the anchor/standalone + cap contract.
 *
 * @param props - {@link BadgeBaseProps}
 */
const BadgeBase = ({
    children,
    count,
    max,
    dot = false,
    showZero = false,
    color = "danger",
    size = "md",
    placement = "top-right",
    isSkeleton = false,
    classNames,
}: BadgeBaseProps) => {
    if (isSkeleton) {
        // Leaf skeleton: a dot shimmer when `dot`, otherwise a short count pill.
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="Badge"
                className={cn(dot ? "size-2.5 rounded-full" : "h-4 w-6 rounded-full", classNames)}

            />
        )
    }

    // A count of 0 hides the badge entirely (unless showZero) — no anchor decoration for "nothing".
    const hidden = !dot && count !== undefined && count <= 0 && !showZero
    const label = dot ? undefined : max !== undefined && count !== undefined && count > max ? `${max}+` : count

    const badge = hidden ? null : (
        <HeroBadge
            // Root marker only when this IS the root — with `children`, `Badge.Anchor`
            // below is the root instead, and this element becomes its nested part.
            data-tier={!children ? "atom" : undefined}
            data-component={!children ? "Badge" : undefined}
            color={color}
            size={size}
            placement={placement}
            className={cn(dot && "min-w-0 p-0", !children && "static", classNames)}

        >
            {label}
        </HeroBadge>
    )

    if (!children) {
        // Standalone: no anchor wrapper, the badge sits inline in normal flow.
        return badge
    }
    return (
        <HeroBadge.Anchor data-tier="atom" data-component="Badge">
            {/* Caller slot — `children` belongs to whoever anchors on this badge,
                not to Badge's own anatomy, so this wrapper stays unbadged. */}
            <span className="inline-flex">
                {children}
            </span>
            {badge}
        </HeroBadge.Anchor>
    )
}

/**
 * `Badge.*` — the badge ATOM namespace. `Badge` is the single constrained
 * badge; count / dot / cap / standalone are LEAVES of it (prop-driven).
 */
export { BadgeBase as Badge }

/** Tier metadata for `Badge`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "Badge" } as const

/** @noSkeleton renders a rule between two things — there is no value behind it to wait for. */
/**
 * ATOM — `Divider`: wraps HeroUI `Separator` directly (HeroUI has no "Divider";
 * renamed for the app's vocabulary). A leaf atom — it builds none of our own storied
 * atoms, so it has no atom-tier dep; `Label` is an internal slot for the free-form
 * label, not a dep. Every rule it draws is a direct `Separator` render (`tier:
 * "heroui"`).
 *
 * One prop = one leaf: `orientation` · `variant` · `label`, each leaf rendering every
 * value in full. Each value is a `states[]` entry with its own `why` and `code`.
 */
import type { ReactNode } from "react"
import { Separator as HeroSeparator, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * ATOM — `Divider`: the ONE constrained divider atom over HeroUI Separator.
 *
 * A dividing line, distinguished by PROP (leaf = composition):
 *   • horizontal            → `<Divider />` (default)
 *   • vertical              → `<Divider orientation="vertical" />` (needs a parent with height)
 *   • with a centered label → `<Divider label="OR" />` (rule | label | rule)
 *   • inline mark           → `<Divider shape="inline" />` (a glyph sitting inside running text)
 *
 * HeroUI has NO `Divider` — the atom wraps `Separator` (renamed for the app's
 * vocabulary). A label is only valid when `orientation="horizontal"` (ignored on
 * vertical). `shape="inline"` skips `Separator` entirely: `orientation` and
 * `variant` describe a line's geometry, and an inline mark has neither — it is a
 * glyph the width of a character, not a track the width of its container. The atom
 * has NO skeleton (a static line, nothing to load).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Divider orientation. */
export type DividerOrientation = "horizontal" | "vertical"

/** Line weight/tone (HeroUI Separator `variant`). Ignored when `shape` is `inline`. */
export type DividerVariant = "default" | "secondary" | "tertiary"

/** Visual form the divider takes. */
export type DividerShape =
    /** A HeroUI Separator line — stretches to fill its track. */
    | "rule"
    /** A small glyph sitting on the surrounding text's baseline, sized and coloured for running text. */
    | "inline"

/** Props for {@link DividerBase}. */
export interface DividerBaseProps {
    /** Orientation. Default `horizontal`. Ignored when `shape` is `inline`. */
    orientation?: DividerOrientation
    /** Line tone. Default `default`. Ignored when `shape` is `inline`. */
    variant?: DividerVariant
    /** Optional centered label (horizontal only) → rule · label · rule. Ignored when `shape` is `inline`. */
    label?: ReactNode
    /**
     * Visual form. Default `rule`. `inline` renders a baseline mark sized for
     * running text and coloured `currentColor`, for a divider that sits between
     * two pieces of text rather than a track spanning a container.
     */
    shape?: DividerShape
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The base divider atom. See file header for the orientation + label contract.
 *
 * @param props - {@link DividerBaseProps}
 */
const DividerBase = ({
    orientation = "horizontal",
    variant = "default",
    label,
    shape = "rule",
    classNames,
}: DividerBaseProps) => {
    // An inline mark: a glyph on the surrounding text's baseline, not a Separator
    // track — it takes `currentColor` and no fixed size, so it tints and scales
    // with whatever row it sits in.
    if (shape === "inline") {
        return (
            <span
                aria-hidden
                data-tier="atom"
                data-component="Divider"

                className={cn("text-current select-none", classNames)}
            >
                ·
            </span>
        )
    }
    // A labelled divider (horizontal only): a rule on each side of centered text.
    if (label !== undefined && orientation === "horizontal") {
        return (
            <div
                data-tier="atom"
                data-component="Divider"
                className={cn("flex w-full items-center gap-3", classNames)}

            >
                <HeroSeparator
                    orientation="horizontal"
                    variant={variant}
                    className="flex-1"

                />
                {/* Caller slot — `label` is free-form content the caller passed in,
                    not part of Divider's own anatomy, so this span stays unbadged. */}
                <span className="text-muted shrink-0 text-xs">
                    {label}
                </span>
                <HeroSeparator
                    orientation="horizontal"
                    variant={variant}
                    className="flex-1"

                />
            </div>
        )
    }
    return (
        <HeroSeparator
            data-tier="atom"
            data-component="Divider"
            orientation={orientation}
            variant={variant}
            className={cn(classNames)}

        />
    )
}

/**
 * `Divider.*` — the divider ATOM namespace. `Divider` is the single
 * constrained divider; orientation / label are LEAVES of it (prop-driven).
 */
export { DividerBase as Divider }

/** Tier metadata for `Divider`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "Divider" } as const

"use client"

import React, { useEffect, useState } from "react"
import type { ComponentType, SVGProps } from "react"
import { cn, Skeleton as HeroSkeleton } from "@heroui/react"
import type { AlertStatus } from "@sb-components/atoms/feedback/Alert/Alert"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ATOM — `IconTile`: the avatar frame of a thing (course, project, section…).
 *
 * One prop = one leaf, each rendering every state the prop produces: `tone` · `size` ·
 * `src` (a cover image over the icon) · `isSkeleton`. Props with no visual (`alt`,
 * `className`) get no leaf. The tile is always round. `icon` has no leaf of its own —
 * it is required content (except while `isSkeleton`), not a caller-toggled axis.
 *
 * The icon takes a component (`icon={GraduationCapIcon}`), not JSX; the atom forces
 * its scale per `size`. In the anatomy, `Tile`/`Cover`/`Icon` are plain elements
 * (unnamed); only `Skeleton` is a nameable HeroUI node.
 */

/**
 * Visual tone of the tile (drives the tinted background + icon colour).
 * Alias of {@link AlertStatus}, not a redeclaration — the same five values,
 * with `default` as neutral rather than a separate `neutral` value.
 */
export type IconTileTone = AlertStatus

/** Size of the tile. */
export type IconTileSize = "sm" | "md" | "lg"

/** Two weight steps for the glyph; only a glyph smaller than `size-5` needs `bold`. */
export type IconWeight = "regular" | "bold"

/**
 * Icon is passed in as a COMPONENT (e.g. `GraduationCapIcon`); the atom renders
 * it and forces its own scale at the tile's size. Typed as `SVGProps` plus an
 * optional `weight`, not against Phosphor's own `Icon` type, so this file does
 * not depend on one icon provider.
 */
export type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: IconWeight }>

/** Shared props — EXCEPT the `icon`/`isSkeleton` pair, see {@link IconTileProps}. */
interface IconTileOwnProps {
    /**
     * Optional cover image. When set, it FILLS the tile (`object-cover`, centered —
     * a 16:9 source is cropped to the square frame) instead of the icon; falls back
     * to `icon` when absent/empty.
     */
    src?: string | null
    /** Alt text for the cover image (decorative tile — usually the entity title). */
    alt?: string
    /** Tinted background + icon colour. Defaults to "accent". */
    tone?: IconTileTone
    /** Tile size. Defaults to "md" (64px). */
    size?: IconTileSize
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * `icon` is required when rendering the real tile, not needed when
 * `isSkeleton` (the shimmer box has no icon inside). Same union shape as
 * `ChipBaseProps`/`TypographyProps`.
 */
export type IconTileProps = IconTileOwnProps &
    (
        | {
            /** `true` → renders a shimmer box at the exact tile size, in place of content. */
            isSkeleton: true
            /** The icon component (vd phosphor `*Icon`) — fallback when no {@link IconTileOwnProps.src}. */
            icon?: IconComponent
        }
        | {
            isSkeleton?: false
            /** The icon component (vd phosphor `*Icon`) — fallback when no {@link IconTileOwnProps.src}. */
            icon: IconComponent
        }
    )

/** tone → tinted background + icon colour. */
const TONE: Record<IconTileTone, string> = {
    accent: "bg-accent-soft text-accent-soft-foreground",
    success: "bg-success-soft text-success-soft-foreground",
    warning: "bg-warning-soft text-warning-soft-foreground",
    danger: "bg-danger-soft text-danger-soft-foreground",
    info: "bg-info-soft text-info-soft-foreground",
    default: "bg-default text-muted",
}

/**
 * Corner rounding — round, a single fixed shape (no `shape` prop/axis).
 *
 * `src` (the real app) currently uses square rounding by size instead and has
 * no `shape` prop; the two are not yet in sync.
 */
const SHAPE_CLASS = "rounded-full"

/**
 * size → the tile's box (corner rounding is {@link SHAPE_CLASS}'s job, kept separate).
 *
 * Default `sm` = `size-10` (40px) with icon `size-5` — the standard pairing for
 * an `IconTile + TitledText` row or an empty state. Icon size is a function of
 * tile size ({@link SIZE_ICON}); callers cannot tune it separately.
 */
const SIZE_BOX: Record<IconTileSize, string> = {
    sm: "size-10",
    md: "size-16",
    lg: "size-20",
}

/**
 * size → the inner icon size. All three steps are `size-5` or above, so no
 * `weight` is passed (the glyph stays `regular`); only a glyph under `size-5`
 * needs `bold`, and IconTile has no step that small.
 */
const SIZE_ICON: Record<IconTileSize, string> = {
    sm: "size-5",
    md: "size-6",
    lg: "size-8",
}

/**
 * A framed icon tile — a soft tinted square (`bg-{tone}/20`) with the icon
 * centered inside, used as the avatar of a *thing* (course, project, section…)
 * to give it breathing room and a consistent identity. The icon auto-sizes and
 * inherits the tone colour; pass the icon COMPONENT (not JSX) and the tile
 * renders + scales it itself. Pure/props-only; owns its look.
 *
 * @param props - {@link IconTileProps}
 */
const IconTileBase = ({
    icon: Icon,
    src,
    alt = "",
    tone = "accent",
    size = "sm",
    isSkeleton = false,
    classNames,
}: IconTileProps) => {
    // a broken cover URL (404 / unsynced asset) falls back to the icon instead of a
    // broken-image glyph; reset when the src changes.
    const [failed, setFailed] = useState(false)
    useEffect(() => setFailed(false), [src])
    const showImage = Boolean(src) && !failed

    // The tile is a solid box (icon/image fills it), so the shimmer is the whole
    // box — exact {@link SIZE_BOX}, same rounding. Checked before any content
    // branch so real content never leaks through while loading.
    if (isSkeleton) {
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="IconTile"

                className={cn("shrink-0", SIZE_BOX[size], SHAPE_CLASS, classNames)}
            />
        )
    }

    return (
        // Tile/Cover/Icon are plain elements, not importable components — but the
        // tile itself IS the atom, so it badges as its own name like any other
        // atom's root (Rule 10); there is nothing here for a caller to name better.
        <div
            aria-hidden
            data-tier="atom"
            data-component="IconTile"

            className={cn(
                "flex shrink-0 items-center justify-center overflow-hidden",
                SIZE_BOX[size],
                SHAPE_CLASS,
                // skip the tint when a cover image fills the tile
                showImage ? null : TONE[tone],
                classNames,
            )}
        >
            {showImage ? (
                <img
                    src={src ?? undefined}
                    alt={alt}
                    className="size-full object-cover"
                    onError={() => setFailed(true)}
                />
            ) : Icon ? (
                <span aria-hidden className="inline-flex shrink-0">
                    {/* SIZE_ICON is already ≥ size-5 at all three steps, so no
                        `weight` is passed — only a glyph < size-5 forces "bold". */}
                    <Icon className={SIZE_ICON[size]} />
                </span>
            ) : null}
        </div>
    )
}

/** `IconTile.*` — framed icon-tile namespace. */
export { IconTileBase as IconTile }

/** Tier metadata for `IconTile`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "IconTile" } as const

import {
    ProgressBar as HeroProgressBar,
    ProgressCircle as HeroProgressCircle,
    Meter as HeroMeter,
    Skeleton as HeroSkeleton,
    cn,
} from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `Progress.*` — the progress-indicator atom namespace, wrapping HeroUI.
 *
 * Members:
 *   - `ProgressBar` — linear bar for ongoing progress. Determinate (`value`) or
 *     `isIndeterminate` (duration unknown).
 *   - `ProgressCircle` — circular, same progress semantics as Bar.
 *   - `ProgressMeter` — static measurement (capacity, battery, score). Always
 *     determinate — react-aria's Meter has no indeterminate state.
 *
 * Bar/Circle wrap react-aria's ProgressBar; Meter wraps react-aria's Meter. Each
 * member owns its size/color mapping and draws its own leaf skeleton
 * (`isSkeleton`). Track/Fill are internal parts owned by the atom.
 */

/** Fill tone shared by all three members. */
export type ProgressColor = "accent" | "success" | "warning" | "danger" | "default"

/** Size preset shared by all three members. */
export type ProgressSize = "sm" | "md" | "lg"

/** Shared props for the DETERMINATE-or-indeterminate members (Bar · Circle). */
interface ProgressTrackProps {
    /** Current value in `[0, max]`. Ignored when `isIndeterminate`. */
    value?: number
    /** Maximum value = 100% completion. Default `100`. */
    max?: number
    /** Ongoing work of unknown duration — the fill animates instead of measuring a value. */
    isIndeterminate?: boolean
    /** Fill tone. Default `accent`; pass a semantic tone when the VALUE carries meaning. */
    color?: ProgressColor
    /** Size preset. Default `md`. */
    size?: ProgressSize
    /** Accessible name (announced by screen readers). */
    ariaLabel?: string
    /** Render the leaf skeleton instead of the indicator. */
    isSkeleton?: boolean
    /**
     * Track thickness. `"compact"` is the labelled-meter density (`h-1`);
     * omit for the atom's own preset size.
     */
    trackDensity?: "default" | "compact"
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/** Per-size circle diameter (skeleton match + `ProgressCircle` doesn't force a box). */
const CIRCLE_BOX: Record<ProgressSize, string> = { sm: "size-10", md: "size-14", lg: "size-20" }

/** `ProgressBar` — linear progress (HeroUI ProgressBar). Determinate or indeterminate. */
const ProgressBar = ({
    value = 0,
    max = 100,
    isIndeterminate = false,
    color = "accent",
    size = "md",
    ariaLabel = "Progress",
    isSkeleton = false,
    trackDensity = "default",
    classNames,
}: ProgressTrackProps) => {
    if (isSkeleton) {
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="ProgressBar"
                className={cn(trackDensity === "compact" ? "h-1" : "h-2", "w-full rounded-full", classNames)}

            />
        )
    }
    return (
        <HeroProgressBar
            data-tier="atom"
            data-component="ProgressBar"
            aria-label={ariaLabel}
            value={value}
            maxValue={max}
            isIndeterminate={isIndeterminate}
            color={color}
            size={size}
            className={cn("w-full", classNames)}
        >
            <HeroProgressBar.Track className={trackDensity === "compact" ? "h-1" : undefined}>
                <HeroProgressBar.Fill />
            </HeroProgressBar.Track>
        </HeroProgressBar>
    )
}

/** `ProgressCircle` — circular progress (HeroUI ProgressCircle). Determinate or indeterminate. */
const ProgressCircle = ({
    value = 0,
    max = 100,
    isIndeterminate = false,
    color = "accent",
    size = "md",
    ariaLabel = "Progress",
    isSkeleton = false,
    classNames,
}: ProgressTrackProps) => {
    if (isSkeleton) {
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="ProgressCircle"
                className={cn("rounded-full", CIRCLE_BOX[size], classNames)}

            />
        )
    }
    return (
        <HeroProgressCircle
            data-tier="atom"
            data-component="ProgressCircle"
            aria-label={ariaLabel}
            value={value}
            maxValue={max}
            isIndeterminate={isIndeterminate}
            color={color}
            size={size}
            className={cn(classNames)}
        >
            <HeroProgressCircle.Track

            >
                <HeroProgressCircle.TrackCircle />
                <HeroProgressCircle.FillCircle

                />
            </HeroProgressCircle.Track>
        </HeroProgressCircle>
    )
}

/** Props shared by {@link Meter}, excluding the `value`/`isSkeleton` pair. */
interface MeterOwnProps {
    /** Maximum value = full. Default `100`. */
    max?: number
    /** Tone. Default `accent`; pass success/warning/danger to signal a threshold band. */
    color?: ProgressColor
    /** Size preset. Default `md`. */
    size?: ProgressSize
    /** Accessible name (announced by screen readers). */
    ariaLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * `value` is required for a live meter, optional when `isSkeleton` — the
 * shimmer has nothing measured yet to show.
 */
type MeterProps = MeterOwnProps &
    (
        | { isSkeleton: true; value?: number }
        | { isSkeleton?: false; value: number }
    )

/** `ProgressMeter` — static gauge (HeroUI Meter). Always determinate; tone signals a band. */
const Meter = ({
    value,
    max = 100,
    color = "accent",
    size = "md",
    ariaLabel = "Meter",
    isSkeleton = false,
    classNames,
}: MeterProps) => {
    if (isSkeleton) {
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="ProgressGauge"
                className={cn("h-2 w-full rounded-full", classNames)}

            />
        )
    }
    return (
        <HeroMeter
            data-tier="atom"
            data-component="ProgressGauge"
            aria-label={ariaLabel}
            value={value}
            maxValue={max}
            color={color}
            size={size}
            className={cn("w-full", classNames)}
        >
            <HeroMeter.Track

            >
                <HeroMeter.Fill

                />
            </HeroMeter.Track>
        </HeroMeter>
    )
}

/**
 * `Progress.*` — progress-indicator atom namespace. `Bar`/`Circle` are progress
 * (determinate/indeterminate); `Gauge` is a static measurement (determinate only).
 * Exported as `ProgressGauge` rather than `ProgressMeter` because `ProgressMeter`
 * is the name of a separate composite block component.
 */
export { ProgressBar, ProgressCircle, Meter as ProgressGauge }

/** Tier metadata for `component`, used by the component registry/Storybook lookup. */
export const meta = [
    { tier: "atom", name: "ProgressBar" },
    { tier: "atom", name: "ProgressCircle" },
    { tier: "atom", name: "ProgressGauge" },
] as const

/** Folder-matching compound namespace (export-matches-folder / ATOM-11 sync). */
export const Progress = {
    Bar: ProgressBar,
    Circle: ProgressCircle,
    Gauge: Meter,
} as const

import { Spinner as HeroSpinner, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * @noSkeleton the spinner IS the loading indicator — a shimmer standing in for one is circular.
 *
 * ATOM — `Spinner`: wraps HeroUI Spinner directly, only forcing `size`/`tone`.
 *
 * LEAF atom — it composes no atom of our own with a story, so it has no atom-tier dep.
 * It renders one `@heroui/react` import directly, so `HeroSpinner` enters the tree with
 * `tier: "heroui"` (no `storyId`, the library has no story of ours to jump to).
 */

/** Spinner size preset. */
export type SpinnerSize = "sm" | "md" | "lg" | "xl"

/** Spinner tone. `current` inherits the surrounding text colour (e.g. inside a button). */
export type SpinnerTone = "accent" | "current" | "danger" | "success" | "warning"

/** Props for {@link SpinnerBase}. */
export interface SpinnerBaseProps {
    /** Size preset. Default `md`. */
    size?: SpinnerSize
