    prefixIcon: Prefix,
    suffixIcon: Suffix,
    iconSlide = false,
    truncate = false,
    lineClamp,
    noWrap = false,
    preserveWhitespace = false,
    isInline = false,
    align,
    tabularNums = false,
    isSkeleton = false,
    classNames,
    size = "base",
