                data-tier="atom"
                data-component="Typography"
                type="code"
                className={cn(
                    COLOR_CLS[color ?? "default"],
                    align ? ALIGN_CLS[align] : null,
                    lineClamp ? CLAMP_CLS[lineClamp] : truncate ? "block truncate" : null,
                    noWrap && NO_WRAP_CLS,
