/** `ProgressCircle` — circular progress (HeroUI ProgressCircle). Determinate or indeterminate. */
const ProgressCircle = ({
    value = 0,
    max = 100,
    isIndeterminate = false,
    color = "accent",
    size = "md",
    ariaLabel = "Progress",
    isSkeleton = false,
    classNames,
}: ProgressTrackProps) => {
    if (isSkeleton) {
        return (
            <HeroSkeleton
