    siblings = 1,
    isSkeleton = false,
    classNames,
}: PaginationBaseProps) => {
    const slots = useMemo(() => buildSlots(currentPage, totalPages, siblings), [currentPage, totalPages, siblings])

    /** Go to the previous page, clamped to the first page. */
