const PaginationLink = ({ pageNumber, isActive, onPageChange }: PaginationLinkProps) => {
    const onPress = useCallback(() => onPageChange(pageNumber), [pageNumber, onPageChange])
    return (
        <HeroPagination.Item>
            <HeroPagination.Link
                isActive={isActive}
                onPress={onPress}
            >
                {pageNumber}
            </HeroPagination.Link>
        </HeroPagination.Item>
    )
}

